CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS games(id TEXT PRIMARY KEY,source TEXT NOT NULL,url TEXT,pgn TEXT NOT NULL,date TEXT NOT NULL,owner TEXT NOT NULL,color TEXT NOT NULL,opponent TEXT NOT NULL,white TEXT,black TEXT,rating INTEGER,opponent_rating INTEGER,result TEXT,time_class TEXT,time_control TEXT,opening TEXT,plies INTEGER NOT NULL,player_moves INTEGER NOT NULL,analysis_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS moves(game_id TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,ply INTEGER NOT NULL,fen TEXT NOT NULL,uci TEXT NOT NULL,san TEXT NOT NULL,color TEXT NOT NULL,phase TEXT NOT NULL,PRIMARY KEY(game_id,ply));
CREATE TABLE IF NOT EXISTS analysis(game_id TEXT NOT NULL,ply INTEGER NOT NULL,settings_key TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(game_id,ply),FOREIGN KEY(game_id,ply) REFERENCES moves(game_id,ply) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS engine_cache(key TEXT PRIMARY KEY,result TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',progress INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,checkpoint TEXT NOT NULL DEFAULT '{}',result TEXT,error TEXT,created INTEGER NOT NULL,heartbeat INTEGER,available INTEGER NOT NULL DEFAULT 0,cancel INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS job_queue ON jobs(status,available,created);
CREATE TABLE IF NOT EXISTS provider_cache(key TEXT PRIMARY KEY,body TEXT NOT NULL,etag TEXT,modified TEXT,expires INTEGER NOT NULL,fetched INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS repertoires(id TEXT PRIMARY KEY,name TEXT NOT NULL,english TEXT NOT NULL,color TEXT NOT NULL,notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lines(id TEXT PRIMARY KEY,repertoire_id TEXT NOT NULL REFERENCES repertoires(id) ON DELETE CASCADE,name TEXT NOT NULL,moves TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS repertoire_edges(repertoire_id TEXT NOT NULL REFERENCES repertoires(id),position TEXT NOT NULL,uci TEXT NOT NULL,preferred INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(repertoire_id,position,uci));
CREATE TABLE IF NOT EXISTS position_notes(repertoire_id TEXT NOT NULL,position TEXT NOT NULL,notes TEXT NOT NULL,PRIMARY KEY(repertoire_id,position));
CREATE TABLE IF NOT EXISTS training(repertoire_id TEXT NOT NULL,position TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,mistakes INTEGER NOT NULL DEFAULT 0,unaided INTEGER NOT NULL DEFAULT 0,assisted INTEGER NOT NULL DEFAULT 0,streak INTEGER NOT NULL DEFAULT 0,interval REAL NOT NULL DEFAULT 0,due INTEGER NOT NULL,last INTEGER,PRIMARY KEY(repertoire_id,position));
CREATE TABLE IF NOT EXISTS training_events(id TEXT PRIMARY KEY,repertoire_id TEXT NOT NULL,position TEXT NOT NULL,line_id TEXT,played TEXT,correct INTEGER NOT NULL,assisted INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS line_training(line_id TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,unaided INTEGER NOT NULL DEFAULT 0,last INTEGER);
CREATE TABLE IF NOT EXISTS review(game_id TEXT NOT NULL,ply INTEGER NOT NULL,due INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,streak INTEGER NOT NULL DEFAULT 0,interval REAL NOT NULL DEFAULT 0,PRIMARY KEY(game_id,ply));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,expires INTEGER NOT NULL);
